get_search_settings.code:
use WebCommander\Sdk\Resources\Settings\SearchSettings\SearchSettings;

$response = SearchSettings::getSearchSettings($client);

$settings = $response->map['search_settings'];
echo 'placeholder: ', $settings['searchable_content']['placeholder_text'], PHP_EOL;
foreach ($settings['search_fields']['fields'] as $row) {
    echo $row['priority'], ' ', $row['field'], PHP_EOL;
}

patch_search_settings.code:
use WebCommander\Sdk\Resources\Settings\SearchSettings\SearchSettings;

$response = SearchSettings::patchSearchSettings($client, [
    'search_settings' => [
        'searchable_content' => ['placeholder_text' => 'Search products'],
        'search_fields' => ['match_keywords_exactly' => true],
    ],
]);

$settings = $response->map['search_settings'];
echo $settings['searchable_content']['placeholder_text'], PHP_EOL;
echo $settings['search_fields']['match_keywords_exactly'] ? 'true' : 'false', PHP_EOL;

put_search_settings_section.code:
use WebCommander\Sdk\Resources\Settings\SearchSettings\SearchSettings;

$response = SearchSettings::putSearchSettingsSection($client, 'search_fields', [
    'search_fields' => ['match_keywords_exactly' => true, 'match_full_sentences' => false, 'fields' => [
        ['field' => 'title', 'priority' => 1], ['field' => 'tags', 'priority' => 2],
        ['field' => 'category', 'priority' => 3], ['field' => 'description', 'priority' => 4],
        ['field' => 'sku', 'priority' => 5], ['field' => 'brand', 'priority' => 6],
    ]],
]);

echo count($response->map['search_fields']['fields']), ' fields', PHP_EOL;

